export interface ConfigInput {
  /**
   * The setting key (e.g., "theme", "model", "permissions.defaultMode")
   */
  setting: string;
  /**
   * The new value. Omit to get current value.
   */
  value?: string | boolean | number;
}

export interface ConfigOutput {
  success: boolean;
  operation?: "get" | "set";
  setting?: string;
  value?: unknown;
  previousValue?: unknown;
  newValue?: unknown;
  error?: string;
}
